 public static synchronized JSONObject install(){/*BR_JSON_WRAP_106*/try{JSONArray ev=new JSONArray(),ct=new JSONArray();for(Rule r:RULES){String id="tasha-"+r.kind+"-"+slug(r.name)+"-r1";String loc=SOURCE_FILE+" pp. "+r.p1+(r.p2==r.p1?"":"-"+r.p2)+" - "+r.pt;JSONObject e=new JSONObject().put("evidence_id",id).put("content_kind",r.kind).put("content_name",r.name).put("source_book",BOOK).put("source_locator",loc).put("source_sha256",SOURCE_SHA256).put("revision",1);JSONObject basis=new JSONObject().put("source_type","reviewed_evidence").put("evidence_id",id).put("content_kind",r.kind).put("content_name",r.name).put("source_book",BOOK).put("source_locator",loc).put("source_sha256",SOURCE_SHA256).put("revision",1);JSONObject m=new JSONObject().put("resolution_mode","compiled_source_rules").put("source_bound",true).put("rag_required",false).put("auto_mutation_allowed",false).put("gameplay_resolution_required",true).put("source_name_ptbr",r.pt).put("source_page_start",r.p1).put("source_page_end",r.p2).put("rules_text_ptbr",r.text).put("source_sha256",SOURCE_SHA256);if(!r.owner.isEmpty())m.put("class",r.owner);ev.put(e);ct.put(new JSONObject().put("kind",r.kind).put("name",r.name).put("mechanics",m).put("mechanical_basis",basis));}JSONObject x=AuthorizedContentTransactionEngine.install(ev,ct);return x.put("descriptor",descriptor()).put("source_bound_records",RULES.length);}catch(RuntimeException __brJsonRuntime106){throw __brJsonRuntime106;}catch(Exception __brJsonChecked106){throw new IllegalStateException(__brJsonChecked106);}}
 public static JSONObject readiness(){/*BR_JSON_WRAP_106*/try{JSONObject d=descriptor();int sc=CompiledContentMechanicsEngine.count("subclass"),sp=CompiledContentMechanicsEngine.count("spell"),it=CompiledContentMechanicsEngine.count("item");return new JSONObject().put("subclasses",sc).put("spells",sp).put("items",it).put("expected_subclasses",d.optInt("subclasses")).put("expected_spells",d.optInt("spells")).put("expected_items",d.optInt("items")).put("complete",sc>=d.optInt("subclasses")&&sp>=d.optInt("spells")&&it>=d.optInt("items")).put("source_sha256",SOURCE_SHA256);}catch(RuntimeException __brJsonRuntime106){throw __brJsonRuntime106;}catch(Exception __brJsonChecked106){throw new IllegalStateException(__brJsonChecked106);}}
